B.F1=s(["\u0c9c","\u0cab\u0cc6","\u0cae\u0cbe","\u0c8f","\u0cae\u0cc7","\u0c9c\u0cc2","\u0c9c\u0cc1","\u0c86","\u0cb8\u0cc6","\u0c85","\u0ca8","\u0ca1\u0cbf"],t.s)
B.F2=s(["\u062d","\u0646","\u062b","\u0631","\u062e","\u062c","\u0633"],t.s)
